#!/usr/bin/env python3import mathimport timefrom collections import dequeimport rclpyfrom rclpy.node import Nodefrom rclpy.qos import (    QoSProfile,    ReliabilityPolicy,    HistoryPolicy,    DurabilityPolicy,)from rclpy.action import ActionClientfrom nav_msgs.msg import OccupancyGrid, Odometryfrom nav2_msgs.action import NavigateToPosefrom geometry_msgs.msg import PoseStampedclass FrontierExplorer(Node):    def __init__(self):        super().__init__('frontier_explorer')        self.map_topic = '/projected_map'        self.odom_topic = '/odom_ground_truth'        map_qos = QoSProfile(            reliability=ReliabilityPolicy.RELIABLE,            durability=DurabilityPolicy.VOLATILE,            history=HistoryPolicy.KEEP_LAST,            depth=10,        )        odom_qos = QoSProfile(            reliability=ReliabilityPolicy.BEST_EFFORT,            durability=DurabilityPolicy.VOLATILE,            history=HistoryPolicy.KEEP_LAST,            depth=10,        )        self.create_subscription(            OccupancyGrid,            self.map_topic,            self.map_callback,            map_qos        )        self.create_subscription(            Odometry,            self.odom_topic,            self.odom_callback,            odom_qos        )        self.nav_client = ActionClient(self, NavigateToPose, 'navigate_to_pose')        self.map_data = None        self.map_width = 0        self.map_height = 0        self.map_res = 0.0        self.map_origin_x = 0.0        self.map_origin_y = 0.0        self.robot_x = None        self.robot_y = None        self.robot_yaw = None        self.goal_x = None        self.goal_y = None        self.goal_cluster_id = None        self.goal_active = False        self.current_goal_handle = None        self.occ_threshold = 50        self.safety_radius_cells = 2        self.min_goal_dist = 1.2        self.max_goal_dist = 8.0        self.frontier_min_cluster_size = 8        self.frontier_search_window_cells = 200        self.last_log_time = 0.0        self.have_logged_map = False        self.have_logged_odom = False        self.last_progress_x = None        self.last_progress_y = None        self.last_progress_time = time.time()        self.progress_check_period = 12.0        self.min_progress_dist = 0.20        self.rejected_clusters = {}        self.reject_duration = 45.0        self.timer = self.create_timer(1.0, self.control_loop)        self.get_logger().info('Nav2 frontier explorer started')        self.get_logger().info(f'Subscribing to map:  {self.map_topic}')        self.get_logger().info(f'Subscribing to odom: {self.odom_topic}')        self.get_logger().info('Using Nav2 action: navigate_to_pose')    def map_callback(self, msg: OccupancyGrid):        self.map_width = msg.info.width        self.map_height = msg.info.height        self.map_res = msg.info.resolution        self.map_origin_x = msg.info.origin.position.x        self.map_origin_y = msg.info.origin.position.y        self.map_data = list(msg.data)        if not self.have_logged_map:            self.get_logger().info(                f'Received map: {self.map_width}x{self.map_height}, res={self.map_res:.3f}'            )            self.have_logged_map = True    def odom_callback(self, msg: Odometry):        self.robot_x = msg.pose.pose.position.x        self.robot_y = msg.pose.pose.position.y        q = msg.pose.pose.orientation        siny_cosp = 2.0 * (q.w * q.z + q.x * q.y)        cosy_cosp = 1.0 - 2.0 * (q.y * q.y + q.z * q.z)        self.robot_yaw = math.atan2(siny_cosp, cosy_cosp)        if not self.have_logged_odom:            self.get_logger().info(                f'Received odom: x={self.robot_x:.2f}, y={self.robot_y:.2f}, yaw={self.robot_yaw:.2f}'            )            self.have_logged_odom = True    def normalize_angle(self, a: float):        while a > math.pi:            a -= 2.0 * math.pi        while a < -math.pi:            a += 2.0 * math.pi        return a    def world_to_map(self, x: float, y: float):        mx = int((x - self.map_origin_x) / self.map_res)        my = int((y - self.map_origin_y) / self.map_res)        if 0 <= mx < self.map_width and 0 <= my < self.map_height:            return mx, my        return None    def map_to_world(self, mx: int, my: int):        x = self.map_origin_x + (mx + 0.5) * self.map_res        y = self.map_origin_y + (my + 0.5) * self.map_res        return x, y    def idx(self, mx: int, my: int):        return my * self.map_width + mx    def cell(self, mx: int, my: int):        return self.map_data[self.idx(mx, my)]    def is_free(self, mx: int, my: int):        v = self.cell(mx, my)        return 0 <= v < self.occ_threshold    def is_unknown(self, mx: int, my: int):        return self.cell(mx, my) == -1    def is_occupied(self, mx: int, my: int):        return self.cell(mx, my) >= self.occ_threshold    def neighbors8(self, mx: int, my: int):        for dy in (-1, 0, 1):            for dx in (-1, 0, 1):                if dx == 0 and dy == 0:                    continue                nx = mx + dx                ny = my + dy                if 0 <= nx < self.map_width and 0 <= ny < self.map_height:                    yield nx, ny    def is_frontier_cell(self, mx: int, my: int):        if not self.is_free(mx, my):            return False        for nx, ny in self.neighbors8(mx, my):            if self.is_unknown(nx, ny):                return True        return False    def is_safe_cell(self, mx: int, my: int):        for dy in range(-self.safety_radius_cells, self.safety_radius_cells + 1):            for dx in range(-self.safety_radius_cells, self.safety_radius_cells + 1):                nx = mx + dx                ny = my + dy                if not (0 <= nx < self.map_width and 0 <= ny < self.map_height):                    return False                if self.is_occupied(nx, ny):                    return False        return True    def cleanup_rejections(self):        now = time.time()        expired = [k for k, t in self.rejected_clusters.items() if t < now]        for k in expired:            del self.rejected_clusters[k]    def find_frontier_clusters(self):        if self.map_data is None or self.robot_x is None or self.robot_y is None:            return []        robot_cell = self.world_to_map(self.robot_x, self.robot_y)        if robot_cell is None:            return []        rx, ry = robot_cell        r = self.frontier_search_window_cells        min_x = max(0, rx - r)        max_x = min(self.map_width - 1, rx + r)        min_y = max(0, ry - r)        max_y = min(self.map_height - 1, ry + r)        frontier_cells = set()        for my in range(min_y, max_y + 1):            for mx in range(min_x, max_x + 1):                if self.is_frontier_cell(mx, my) and self.is_safe_cell(mx, my):                    frontier_cells.add((mx, my))        visited = set()        clusters = []        for start in frontier_cells:            if start in visited:                continue            q = deque([start])            visited.add(start)            cluster = []            while q:                cx, cy = q.popleft()                cluster.append((cx, cy))                for nx, ny in self.neighbors8(cx, cy):                    if (nx, ny) in frontier_cells and (nx, ny) not in visited:                        visited.add((nx, ny))                        q.append((nx, ny))            if len(cluster) >= self.frontier_min_cluster_size:                clusters.append(cluster)        return clusters    def cluster_centroid(self, cluster):        mx = sum(c[0] for c in cluster) / len(cluster)        my = sum(c[1] for c in cluster) / len(cluster)        return int(round(mx)), int(round(my))    def cluster_id(self, cluster):        return self.cluster_centroid(cluster)    def choose_goal_from_cluster(self, cluster):        cx, cy = self.cluster_centroid(cluster)        candidates = sorted(            cluster,            key=lambda c: (c[0] - cx) ** 2 + (c[1] - cy) ** 2        )        for mx, my in candidates:            wx, wy = self.map_to_world(mx, my)            dist = math.hypot(wx - self.robot_x, wy - self.robot_y)            if dist < self.min_goal_dist or dist > self.max_goal_dist:                continue            return wx, wy        return None    def score_cluster(self, cluster):        cid = self.cluster_id(cluster)        if cid in self.rejected_clusters:            return None        goal = self.choose_goal_from_cluster(cluster)        if goal is None:            return None        wx, wy = goal        dist = math.hypot(wx - self.robot_x, wy - self.robot_y)        target_yaw = math.atan2(wy - self.robot_y, wx - self.robot_x)        yaw_err = abs(self.normalize_angle(target_yaw - self.robot_yaw))        size_bonus = min(len(cluster), 50) * 0.03        score = dist + 0.4 * yaw_err - size_bonus        return score, goal, cid, len(cluster)    def find_best_frontier_goal(self):        self.cleanup_rejections()        clusters = self.find_frontier_clusters()        best = None        best_score = float('inf')        for cluster in clusters:            scored = self.score_cluster(cluster)            if scored is None:                continue            score, goal, cid, size = scored            if score < best_score:                best_score = score                best = (goal[0], goal[1], cid, size)        return best    def send_nav_goal(self, x, y):        if not self.nav_client.wait_for_server(timeout_sec=2.0):            self.get_logger().warn('Nav2 action server not available')            return False        goal_msg = NavigateToPose.Goal()        pose = PoseStamped()        pose.header.frame_id = 'map'        pose.header.stamp = self.get_clock().now().to_msg()        pose.pose.position.x = float(x)        pose.pose.position.y = float(y)        pose.pose.orientation.w = 1.0        goal_msg.pose = pose        self.get_logger().info(f'Sending Nav2 goal: ({x:.2f}, {y:.2f})')        send_future = self.nav_client.send_goal_async(goal_msg)        send_future.add_done_callback(self.goal_response_callback)        self.goal_active = True        return True    def goal_response_callback(self, future):        goal_handle = future.result()        if not goal_handle.accepted:            self.get_logger().warn('Goal rejected by Nav2')            self.goal_active = False            self.current_goal_handle = None            if self.goal_cluster_id is not None:                self.rejected_clusters[self.goal_cluster_id] = time.time() + self.reject_duration            self.goal_x = None            self.goal_y = None            self.goal_cluster_id = None            return        self.get_logger().info('Goal accepted by Nav2')        self.current_goal_handle = goal_handle        result_future = goal_handle.get_result_async()        result_future.add_done_callback(self.goal_result_callback)    def goal_result_callback(self, future):        self.get_logger().info('Nav2 goal finished')        self.goal_active = False        self.current_goal_handle = None        self.goal_x = None        self.goal_y = None        self.goal_cluster_id = None    def cancel_current_goal(self):        if self.current_goal_handle is not None:            self.get_logger().info('Cancelling current Nav2 goal')            cancel_future = self.current_goal_handle.cancel_goal_async()            cancel_future.add_done_callback(lambda _: None)        self.goal_active = False        self.current_goal_handle = None    def reject_current_cluster(self):        if self.goal_cluster_id is not None:            self.rejected_clusters[self.goal_cluster_id] = time.time() + self.reject_duration            self.get_logger().info(f'Rejecting frontier cluster {self.goal_cluster_id}')        self.cancel_current_goal()        self.goal_x = None        self.goal_y = None        self.goal_cluster_id = None    def check_stuck(self):        if self.goal_x is None or self.goal_y is None:            return        now = time.time()        if self.last_progress_x is None or self.last_progress_y is None:            self.last_progress_x = self.robot_x            self.last_progress_y = self.robot_y            self.last_progress_time = now            return        moved = math.hypot(            self.robot_x - self.last_progress_x,            self.robot_y - self.last_progress_y        )        elapsed = now - self.last_progress_time        if moved > self.min_progress_dist:            self.last_progress_x = self.robot_x            self.last_progress_y = self.robot_y            self.last_progress_time = now            return        if self.goal_active and elapsed > self.progress_check_period:            self.get_logger().info('Robot appears stuck; dropping current frontier cluster')            self.reject_current_cluster()            self.last_progress_x = self.robot_x            self.last_progress_y = self.robot_y            self.last_progress_time = now    def control_loop(self):        if self.map_data is None or self.robot_x is None or self.robot_y is None or self.robot_yaw is None:            now = time.time()            if now - self.last_log_time > 1.0:                missing = []                if self.map_data is None:                    missing.append(self.map_topic)                if self.robot_x is None or self.robot_y is None or self.robot_yaw is None:                    missing.append(self.odom_topic)                self.get_logger().info(f'Waiting for: {", ".join(missing)}')                self.last_log_time = now            return        self.check_stuck()        if self.goal_active:            now = time.time()            dist = math.hypot(self.goal_x - self.robot_x, self.goal_y - self.robot_y)            if now - self.last_log_time > 1.0:                self.get_logger().info(                    f'Nav2 goal active: ({self.goal_x:.2f}, {self.goal_y:.2f}) '                    f'cluster={self.goal_cluster_id} dist={dist:.2f}'                )                self.last_log_time = now            return        best = self.find_best_frontier_goal()        if best is None:            now = time.time()            if now - self.last_log_time > 2.0:                self.get_logger().info('No valid frontier cluster found')                self.last_log_time = now            return        goal_x, goal_y, cluster_id, cluster_size = best        self.goal_x = goal_x        self.goal_y = goal_y        self.goal_cluster_id = cluster_id        self.get_logger().info(            f'New frontier cluster goal: ({goal_x:.2f}, {goal_y:.2f}), '            f'cluster={cluster_id}, size={cluster_size}'        )        self.last_progress_x = self.robot_x        self.last_progress_y = self.robot_y        self.last_progress_time = time.time()        self.send_nav_goal(goal_x, goal_y)def main(args=None):    print('Starting Nav2 frontier explorer...')    rclpy.init(args=args)    node = FrontierExplorer()    rclpy.spin(node)    node.destroy_node()    rclpy.shutdown()if __name__ == '__main__':    main()